#!/usr/bin/env python3
"""Harness: run crowbook on markdown text, extract body paragraphs, print repr."""
import subprocess, sys, os, re, tempfile, shutil

REF = "/tmp/ref/crowbook"

def run(md, fmt="html", opts=None, book=None, raw=False):
    d = tempfile.mkdtemp(dir="/tmp/work/typo/tmp")
    mdf = os.path.join(d, "t.md")
    with open(mdf, "w") as f:
        f.write(md)
    if book is None:
        cmd = [REF, "--single", mdf, "-t", fmt, "-o", "-"]
    else:
        bf = os.path.join(d, "book.md")
        with open(bf, "w") as f:
            f.write(book + "\n! t.md\n")
        cmd = [REF, bf, "-t", fmt, "-o", "-"]
    if opts:
        cmd += ["--set"]
        for k, v in opts.items():
            cmd += [k, v]
    p = subprocess.run(cmd, capture_output=True)
    out = p.stdout.decode("utf-8", "replace")
    err = p.stderr.decode("utf-8", "replace")
    if raw:
        return out, err
    return out, err

def paras(out):
    """extract <p ...>...</p> content"""
    return re.findall(r'<p[^>]*>(.*?)</p>', out, re.S)

def body(out, fmt="html"):
    if fmt in ("html",):
        m = re.search(r'<div id = "content">(.*?)</div>', out, re.S)
        if m: return m.group(1)
    return out

def show(md, fmt="html", opts=None, label=None, book=None):
    out, err = run(md, fmt, opts, book)
    ps = paras(out)
    print("=== %s | opts=%s | fmt=%s" % (label or repr(md), opts, fmt))
    for p in ps:
        print("   ", repr(p))
    if err.strip() and "CROWBOOK" not in err:
        print("  ERR:", err.strip()[:300])
    return ps

if __name__ == "__main__":
    os.makedirs("/tmp/work/typo/tmp", exist_ok=True)
    show(sys.argv[1] if len(sys.argv) > 1 else "test: foo")

